sys_ui_action.client_script_v2:
function onClick(g_form) {
    // 1. Show initial loading message
    g_form.addInfoMessage('⏳ AI is analyzing the process... Please wait.');

    // 2. Call the Assessment Script Include asynchronously
    var ga = new GlideAjax('x_168647_aiva.AIVAGenAIAssistant');
    ga.addParam('sysparm_name', 'generateAssessmentAjax');
    ga.addParam('sysparm_record_id', g_form.getUniqueValue());

    // 3. Wait for the Assessment response
    ga.getXMLAnswer(function(response) {
        if (response && !response.startsWith("Error") && !response.startsWith("Exception")) {
            g_form.addInfoMessage('✨ AI Pre-Assessment generated! Now building architecture diagrams... ⏳');

            // 4. Trigger Secondary Call for Architecture Diagrams
            var gaArch = new GlideAjax('x_168647_aiva.AIVAGenAIAssistant');
            gaArch.addParam('sysparm_name', 'generateArchitectureComparison');
            gaArch.addParam('sysparm_record_id', g_form.getUniqueValue());

            gaArch.getXMLAnswer(function(archResponse) {
                if (archResponse && !archResponse.startsWith("Error") && !archResponse.startsWith("Exception")) {
                    g_form.addInfoMessage('✨ Architecture Diagrams generated successfully!');
                } else {
                    g_form.addErrorMessage('Failed to generate architecture diagrams: ' + archResponse);
                }
            });

        } else {
            g_form.addErrorMessage('Failed to generate assessment: ' + response);
        }
    });
}

sys_ui_action.script:
function runAIAssessment() {
    // 1. Show initial loading message
    g_form.addInfoMessage('⏳ AI is analyzing the process... Please wait.');

    // 2. Call the Assessment Script Include asynchronously
    var ga = new GlideAjax('AIVAGenAIAssistant');
    ga.addParam('sysparm_name', 'generateAssessmentAjax');
    ga.addParam('sysparm_record_id', g_form.getUniqueValue());

    // 3. Wait for the Assessment response
    ga.getXMLAnswer(function(response) {
        // Clear the initial message
        g_form.clearMessages();

        if (response && !response.startsWith("Error") && !response.startsWith("Exception")) {
            g_form.addInfoMessage('✨ AI Pre-Assessment generated! Now building architecture diagrams... ⏳');

            // 4. Trigger Secondary Call for Architecture Diagrams
            var gaArch = new GlideAjax('AIVAGenAIAssistant');
            gaArch.addParam('sysparm_name', 'generateArchitectureComparison');
            gaArch.addParam('sysparm_record_id', g_form.getUniqueValue());

            gaArch.getXMLAnswer(function(archResponse) {
                g_form.clearMessages(); // Clear the transition message
                if (archResponse && !archResponse.startsWith("Error") && !archResponse.startsWith("Exception")) {
                    g_form.addInfoMessage('✨ AI Pre-Assessment and Architecture Diagrams generated successfully!');
                } else {
                    g_form.addErrorMessage('Failed to generate architecture diagrams: ' + archResponse);
                }
            });

        } else {
            g_form.addErrorMessage('Failed to generate assessment: ' + response);
        }
    });
}
